const store = $getWorkflowStaticData('global');
if (!store.since) {                 // first run: start from now, so nothing older is sent
  store.since = new Date().toISOString();
  store.afterId = '0';
}
return [{ json: { since: store.since, after_id: store.afterId || '0' } }];

const store = $getWorkflowStaticData('global');
const events = $input.first().json.events || [];
const MB = 1024 * 1024, GB = 1024 * MB;
const num = (v) => (v === null || v === undefined || !Number.isFinite(Number(v)) ? null : Number(v));
const show = (v, f) => (num(v) === null ? 'No data' : f(num(v)));
const mins = (m) => (m > 10 ? Math.round(m / 5) * 5 : Math.max(1, Math.round(m)));
const HEADER = (e) => {
  const server = e.server_name || e.server;
  return e.project ? `Server: ${server} | Project: ${e.project}\n` : `Server: ${server}\n`;
};
const FOOT = '\n\nThis is a warning only. No restart or rollback is started.';
const out = [];
for (const e of events) {
  let body = null;
  if (e.resource === 'memory') {
    body = `Early warning: memory of ${e.container} is rising steadily\n` +
      `Now ${show(e.level_at_open, v => (v / MB).toFixed(0) + ' MB')}` +
      (num(e.limit_value) === null ? ' (limit: No data)' : ` of its ${(num(e.limit_value) / MB).toFixed(0)} MB limit`) +
      (num(e.slope_per_min) === null ? ', rate: No data\n' : `, rising about ${(num(e.slope_per_min) / MB).toFixed(1)} MB a minute\n`) +
      `At this pace it reaches the limit in about ${show(e.est_minutes_at_open, v => mins(v) + ' min')}`;
  } else if (e.resource === 'disk') {
    const pct = num(e.level_at_open) !== null && num(e.limit_value) ? (100 * e.level_at_open / e.limit_value).toFixed(0) + '%' : 'No data';
    body = `Early warning: disk ${e.mountpoint} is filling\n` +
      `Now ${pct} used (${show(e.level_at_open, v => (v / GB).toFixed(1))} of ${show(e.limit_value, v => (v / GB).toFixed(1))} GB), ` +
      `rising about ${show(e.slope_per_min, v => (v * 60 / GB).toFixed(2) + ' GB')} an hour\n` +
      `At this pace it is full in about ${show(e.est_minutes_at_open, v => (v < 120 ? (v / 60).toFixed(1) : Math.round(v / 60)) + ' hours')}`;
  } else if (e.resource === 'restarts') {
    body = `Early warning: ${e.container} is restarting repeatedly\n` +
      `Restarted ${show(e.level_at_open, v => String(v))} times in 15 minutes`;
  }
  if (body) out.push({ json: { text: HEADER(e) + body + FOOT } });
}
if (events.length) {                // move the cursor to the last row read
  const last = events[events.length - 1];
  store.since = last.opened_at;
  store.afterId = last.id;
}
return out;
